window.__MODEL_FILES__ = {"file:///dashboards/games-2025.malloy":"##! experimental { givens }\n\n// =====================================================================\n//  2025 GAMES\n//\n//  Every game of the 2025 season as a scoreboard card, filtered by team,\n//  conference, division and week, and sorted by the reader (kickoff,\n//  thrill index, CFBD excitement, margin, points, upset).\n//\n//  The component (games-2025.tsx) is generated from\n//  components/games-report.tsx by sync-components.mjs and is identical\n//  to games-2026.tsx: everything season-specific lives in THIS file.\n//  Edit the component there, not here.\n// =====================================================================\n\nimport \"../index.malloy\"\nimport \"../givens.malloy\"\n\n#\" Every game of the 2025 season — filter by team, conference or week, and sort by kickoff or by how exciting it was.\n# artifact { title=\"2025 Games\" givens { SEASON='2025' } }\nquery: games_list is games -> {\n  where:\n    Season = 2025,\n    // pinned above; referenced so the pickers' suggest queries narrow to\n    // this season too\n    season_label ~ $SEASON,\n    HomeTeam ~ $TEAM or AwayTeam ~ $TEAM,\n    HomeConference ~ $CONFERENCE or AwayConference ~ $CONFERENCE,\n    HomeClassification ~ $DIVISION or AwayClassification ~ $DIVISION,\n    week_label ~ $GAME_WEEK\n\n  group_by:\n    // ---- when and where ----\n    game_id is Id\n    season is Season\n    week_label\n    week_sort\n    start_date is StartDate\n    start_time_tbd is StartTimeTBD\n    completed is Completed\n    neutral_site is NeutralSite\n    conference_game is ConferenceGame\n    venue is Venue\n    attendance is Attendance\n    notes is Notes\n    bowl is `Playoff BowlName`\n    playoff_round is `Playoff RoundName`\n    has_drive_detail\n\n    // ---- the two teams ----\n    away_team is AwayTeam\n    away_conference is AwayConference\n    away_classification is AwayClassification\n    away_points is AwayPoints\n    away_line_scores is AwayLineScores\n    away_pregame_elo is AwayPregameElo\n    away_seed is `Playoff AwaySeed`\n    home_team is HomeTeam\n    home_conference is HomeConference\n    home_classification is HomeClassification\n    home_points is HomePoints\n    home_line_scores is HomeLineScores\n    home_pregame_elo is HomePregameElo\n    home_seed is `Playoff HomeSeed`\n\n    // ---- how it went ----\n    victory_margin\n    total_points\n    is_overtime\n    is_elo_upset\n    is_comeback_win\n    pregame_elo_edge\n    excitement_index is ExcitementIndex\n    thrill_index\n    thrill_tier\n    thrill_closeness\n    thrill_late_drama\n    thrill_comeback\n    thrill_overtime\n    thrill_scoring\n    thrill_upset\n    thrill_stakes\n\n  order_by: start_date, game_id\n}\n\n#\" Every possession of every game the selected team played this season, for its drive charts.\nquery: team_game_drives is drives -> game_drive_chart + {\n  where:\n    game.Season = 2025,\n    season_label ~ $SEASON,\n    Offense ~ $TEAM or Defense ~ $TEAM,\n    game.week_label ~ $GAME_WEEK\n}\n","file:///dashboards/games-2026.malloy":"##! experimental { givens }\n\n// =====================================================================\n//  2026 GAMES\n//\n//  Every game of the 2026 season as a scoreboard card, filtered by team,\n//  conference, division and week, and sorted by the reader (kickoff,\n//  thrill index, CFBD excitement, margin, points, upset).\n//\n//  The component (games-2026.tsx) is generated from\n//  components/games-report.tsx by sync-components.mjs and is identical\n//  to games-2025.tsx: everything season-specific lives in THIS file.\n//  Edit the component there, not here.\n// =====================================================================\n\nimport \"../index.malloy\"\nimport \"../givens.malloy\"\n\n#\" Every game of the 2026 season — filter by team, conference or week, and sort by kickoff or by how exciting it was.\n# artifact { title=\"2026 Games\" givens { SEASON='2026' } }\nquery: games_list is games -> {\n  where:\n    Season = 2026,\n    // pinned above; referenced so the pickers' suggest queries narrow to\n    // this season too\n    season_label ~ $SEASON,\n    HomeTeam ~ $TEAM or AwayTeam ~ $TEAM,\n    HomeConference ~ $CONFERENCE or AwayConference ~ $CONFERENCE,\n    HomeClassification ~ $DIVISION or AwayClassification ~ $DIVISION,\n    week_label ~ $GAME_WEEK\n\n  group_by:\n    // ---- when and where ----\n    game_id is Id\n    season is Season\n    week_label\n    week_sort\n    start_date is StartDate\n    start_time_tbd is StartTimeTBD\n    completed is Completed\n    neutral_site is NeutralSite\n    conference_game is ConferenceGame\n    venue is Venue\n    attendance is Attendance\n    notes is Notes\n    bowl is `Playoff BowlName`\n    playoff_round is `Playoff RoundName`\n    has_drive_detail\n\n    // ---- the two teams ----\n    away_team is AwayTeam\n    away_conference is AwayConference\n    away_classification is AwayClassification\n    away_points is AwayPoints\n    away_line_scores is AwayLineScores\n    away_pregame_elo is AwayPregameElo\n    away_seed is `Playoff AwaySeed`\n    home_team is HomeTeam\n    home_conference is HomeConference\n    home_classification is HomeClassification\n    home_points is HomePoints\n    home_line_scores is HomeLineScores\n    home_pregame_elo is HomePregameElo\n    home_seed is `Playoff HomeSeed`\n\n    // ---- how it went ----\n    victory_margin\n    total_points\n    is_overtime\n    is_elo_upset\n    is_comeback_win\n    pregame_elo_edge\n    excitement_index is ExcitementIndex\n    thrill_index\n    thrill_tier\n    thrill_closeness\n    thrill_late_drama\n    thrill_comeback\n    thrill_overtime\n    thrill_scoring\n    thrill_upset\n    thrill_stakes\n\n  order_by: start_date, game_id\n}\n\n#\" Every possession of every game the selected team played this season, for its drive charts.\nquery: team_game_drives is drives -> game_drive_chart + {\n  where:\n    game.Season = 2026,\n    season_label ~ $SEASON,\n    Offense ~ $TEAM or Defense ~ $TEAM,\n    game.week_label ~ $GAME_WEEK\n}\n","file:///dashboards/team-rankings.malloy":"##! experimental { givens }\n\n// =====================================================================\n//  TEAM RANKINGS\n//\n//  One row per team: record, points scored and allowed, and drive\n//  efficiency on both sides of the ball. The component\n//  (team-rankings.tsx) draws it as one wide table that re-ranks on a\n//  click of any column header.\n//\n//  The garbage-time checkbox thins the DRIVE columns only. It is applied\n//  on the joined drive sources below rather than in the query's where:,\n//  because a where: on one join would also drop the other join's rows\n//  from the fan-out — and would knock whole games out of the record.\n// =====================================================================\n\nimport \"../index.malloy\"\nimport \"../givens.malloy\"\n\n#(doc) Drives with garbage time left out when the checkbox is on.\nsource: ranking_drives is drives extend {\n  where: $EXCLUDE_GARBAGE = false or not is_garbage_possession\n}\n\n#(doc) Team-games with the (optionally garbage-free) drives each team ran and defended.\nsource: ranking_team_games is team_games extend {\n  join_many: off is ranking_drives on game_id = off.GameId and team = off.Offense\n  join_many: def is ranking_drives on game_id = def.GameId and team = def.Defense\n}\n\n#\" Every team ranked on record, scoring and drive efficiency on both sides of the ball. Click a column header to re-rank.\n# artifact { title=\"Team Rankings\" }\nquery: team_rankings is ranking_team_games -> {\n  where:\n    season_label ~ $SEASON,\n    classification ~ $DIVISION,\n    conference ~ $CONFERENCE\n\n  group_by:\n    team\n    conference\n\n  aggregate:\n    // ---- record ----\n    games_played\n    wins\n    losses\n    win_rate\n    points_per_game\n    points_allowed_per_game\n    avg_scoring_margin\n\n    // ---- offense ----\n    offense_drives is off.count()\n    offense_points_per_drive is off.points_per_drive\n    offense_yards_per_play is off.yards_per_play\n    offense_eckel_rate is off.eckel_rate\n    offense_touchdown_rate is off.touchdown_rate\n    offense_explosive_rate is off.explosive_drive_rate\n    offense_three_and_out_rate is off.three_and_out_rate\n    offense_turnover_rate is off.turnover_rate\n    offense_avg_start is off.avg_start_field_position\n\n    // ---- defense ----\n    defense_points_per_drive is def.points_per_drive\n    defense_yards_per_play is def.yards_per_play\n    defense_eckel_rate is def.eckel_rate\n    defense_three_and_out_rate is def.three_and_out_rate\n    defense_takeaway_rate is def.turnover_rate\n\n    // ---- overall ----\n    net_points_per_drive is off.points_per_drive - def.points_per_drive\n    current_elo\n    strength_of_schedule\n\n  having: games_played > 0\n  order_by: net_points_per_drive desc\n}\n","file:///drives.malloy":"##! experimental.access_modifiers\n\nimport \"raw.malloy\"\n\n// =====================================================================\n//  DRIVES — one row per possession, 2025 and 2026 seasons\n//\n//  Source: drives_raw (raw.malloy), the CollegeFootballData (CFBD)\n//  /drives feed read from huggingface.co/datasets/24601p/cfb-data, one\n//  parquet file per season. Adapted from ../drives.malloy, the 2025-only\n//  model; the counts quoted in the notes below are 2025's. The addition\n//  here is the Eckel rate.\n//\n//  GRAIN: one row per drive (possession). 38,902 rows — the feed's 38,906\n//  less the 4 redundant copies dropped by drive_dedupe_context below.\n//  COVERAGE: 1,659 games — the Division I schedule. Every FBS game\n//  (808 FBS-vs-FBS plus 126 FBS-vs-FCS) and every FCS game (669\n//  FCS-vs-FCS plus 42 against lower divisions) has drive detail. The\n//  2,172 games with no drive rows are Division II and Division III\n//  matchups, which the feed does not track play by play.\n//\n//  FIELD COORDINATES — two systems, both present:\n//    * YardsToGoal   0-100, relative to the OFFENSE: the distance to the\n//                    end zone the offense is attacking. 75 = own 25.\n//    * Yardline      0-100, an absolute stripe on the field: 0 is the\n//                    goal line the AWAY team attacks, 100 is the goal\n//                    line the HOME team attacks. Verified against\n//                    YardsToGoal on 99.3% of rows. This is the coordinate\n//                    to draw a drive chart in, because both teams' drives\n//                    share it.\n//\n//  KNOWN NOISE: 52 rows have an EndYardline outside 0-100 and a handful\n//  of rows carry impossible yardage; StartPeriod 0 appears on 20 rows.\n//  The chart_* dimensions below clamp these so a drive chart stays sane.\n// =====================================================================\n\n// =====================================================================\n//  POSSESSION BOOKKEEPING\n//\n//  Three window functions the garbage-time rules need, computed in one\n//  pass over the same parquet. It reads the file directly rather than\n//  extending drives_base, because drives_base joins THIS back in and a\n//  source cannot derive from itself.\n//\n//    drives_left_in_game          this drive plus every later one\n//    offense_possessions_left     this drive plus this offense's later ones\n//    drives_left_in_period_group  the same, within first half / second\n//                                 half / overtime\n//\n//  Two identities fall out and do all the work downstream:\n//    * the last drive of anything has 1 left\n//    * the DEFENSE's remaining possessions are\n//      drives_left_in_game - offense_possessions_left, because only two\n//      teams have the ball in a game\n// =====================================================================\n\n// =====================================================================\n//  REDUNDANT COPIES — the feed sometimes lists one possession twice.\n//\n//  Every drive the feed knows carries a real id, built from the game id\n//  plus the drive number. A handful of rows instead carry a small\n//  NEGATIVE id: 58 of them across the season, and they are not junk —\n//  54 are real possessions the feed simply had no id for, including\n//  the last possession of the BYU-Arizona double overtime.\n//\n//  The other 4 are copies. Each one restates a possession that is\n//  already present under its real id — same game, same offense, same\n//  period, same plays, same yards, same starting field position — and\n//  differs only in the result string and in which lagging version of\n//  the scoreboard it carries. Left in, they draw a second BYU\n//  touchdown in the second overtime that was never scored.\n//\n//  So the rule is narrow on purpose: drop a SYNTHETIC row only when a\n//  REAL-id row of the same shape outranks it. Shape alone is far too\n//  loose — 120 rows in the season share one, nearly all of them\n//  genuinely distinct possessions in regulation (two 3-play, 6-yard\n//  punts from the same yard line in one quarter is an ordinary\n//  afternoon), and dropping those would delete real football.\n// =====================================================================\n\n#(doc) Marks each drive as either the copy the feed kept or a redundant synthetic restatement of a possession already present under its real id.\nsource: drive_dedupe_context is drives_raw -> {\n  group_by:\n    #(doc) Identifier of the drive this verdict describes.\n    drive_id is Id\n\n    #(doc) The facts that make two rows the same possession: game, offense, period, plays, yards and starting field position.\n    possession_shape is concat(\n      GameId::string, '|', Offense, '|', StartPeriod::string, '|',\n      Plays::string, '|', Yards::string, '|', StartYardsToGoal::string\n    )\n\n  calculate:\n    #(doc) Rank of this row among rows describing the same possession, real feed ids first. 1 is the copy to keep.\n    copy_rank is row_number() { partition_by: possession_shape, order_by: drive_id desc }\n} extend {\n  primary_key: drive_id\n\n  dimension:\n    #(doc) True when this row carries a synthetic negative id AND a real-id row describes the same possession, which makes it a duplicate to drop.\n    is_redundant_copy is drive_id < 0 and copy_rank > 1\n}\n\n#(doc) The drive feed with the redundant copies removed. Everything downstream reads this rather than the raw table, so no query has to remember to filter them.\nsource: drives_deduped is drives_raw extend {\n  join_one: dedupe is drive_dedupe_context on Id = dedupe.drive_id\n  where: not dedupe.is_redundant_copy\n}\n\n#(doc) Possession counts for each drive: how many possessions are left in the game, how many the team with the ball has left, and how many are left in the current half. Used to decide whether a game is still within reach.\nsource: drive_possession_context is drives_deduped -> {\n  group_by:\n    #(doc) Identifier of the drive these counts describe. Join key back to the drive.\n    drive_id is Id\n\n    #(doc) Identifier of the game the drive belongs to.\n    GameId\n\n    #(doc) Team with the ball on the drive.\n    Offense\n\n    #(doc) Drive number within the game.\n    DriveNumber\n\n    #(doc) Segment of the game the drive belongs to: 1 for the first half, 2 for the second half, 3 for overtime.\n    period_group is\n      pick 1 when StartPeriod <= 2\n      pick 2 when StartPeriod <= 4\n      else 3\n\n    #(doc) Score of the team with the ball as the drive began, carried here so the next drive's copy can be compared against it.\n    start_offense_score is StartOffenseScore\n\n    #(doc) Score of the defending team as the drive began, carried here so the next drive's copy can be compared against it.\n    start_defense_score is StartDefenseScore\n\n    #(doc) Home team's score as the feed reports it at the end of the drive, before any repair.\n    raw_home_score is\n      pick EndOffenseScore when IsHomeOffense\n      else EndDefenseScore\n\n    #(doc) Away team's score as the feed reports it at the end of the drive, before any repair.\n    raw_away_score is\n      pick EndDefenseScore when IsHomeOffense\n      else EndOffenseScore\n\n  calculate:\n    #(doc) Number of possessions left in the game counting this one, so the last drive of a game has 1.\n    drives_left_in_game is row_number() { partition_by: GameId, order_by: DriveNumber desc }\n\n    #(doc) Number of possessions the team with the ball has left in the game counting this one.\n    offense_possessions_left is row_number() { partition_by: GameId, Offense, order_by: DriveNumber desc }\n\n    #(doc) Number of possessions left in this half counting this one, so the last drive of a half has 1.\n    drives_left_in_period_group is row_number() { partition_by: GameId, period_group, order_by: DriveNumber desc }\n\n    #(doc) Team with the ball on the next possession of the game. Empty on the last drive.\n    next_offense is lead(Offense) { partition_by: GameId, order_by: DriveNumber }\n\n    #(doc) Score of the next possession's offense as that drive began. Used to check this drive's ending scoreboard against the next drive's opening one.\n    next_start_offense_score is lead(start_offense_score) { partition_by: GameId, order_by: DriveNumber }\n\n    #(doc) Score of the next possession's defense as that drive began.\n    next_start_defense_score is lead(start_defense_score) { partition_by: GameId, order_by: DriveNumber }\n\n    #(doc) Home team's reported score on the previous possession, used to spot a scoreboard spike.\n    prev_home_score is lag(raw_home_score) { partition_by: GameId, order_by: DriveNumber }\n\n    #(doc) Home team's reported score on the next possession, used to spot a scoreboard spike.\n    next_home_score is lead(raw_home_score) { partition_by: GameId, order_by: DriveNumber }\n\n    #(doc) Away team's reported score on the previous possession.\n    prev_away_score is lag(raw_away_score) { partition_by: GameId, order_by: DriveNumber }\n\n    #(doc) Away team's reported score on the next possession.\n    next_away_score is lead(raw_away_score) { partition_by: GameId, order_by: DriveNumber }\n}\n// ---------------------------------------------------------------------\n//  Second stage: repair the running scoreboard.\n//\n//  A score can never go down, so a value standing ABOVE both of its\n//  neighbours is the feed misreporting — in the Pop-Tarts Bowl, BYU's\n//  second possession carries the game's FINAL score (25-21) before\n//  dropping back to 0-7. Replacing each such spike with the previous\n//  possession's score takes the season from 800 drives whose ledger\n//  goes backwards to 235; a one-step monotonic guard on top takes it\n//  to 142, and neither touches the 1,571 of 1,659 games whose last\n//  drive already matches the official final.\n// ---------------------------------------------------------------------\n-> {\n  group_by:\n    drive_id\n    GameId\n    Offense\n    DriveNumber\n    period_group\n    start_offense_score\n    start_defense_score\n    drives_left_in_game\n    offense_possessions_left\n    drives_left_in_period_group\n    next_offense\n    next_start_offense_score\n    next_start_defense_score\n\n    #(doc) Home team's score after the drive, with a scoreboard spike replaced by the previous possession's score.\n    despiked_home_score is\n      pick prev_home_score\n        when prev_home_score is not null and next_home_score is not null\n          and raw_home_score > prev_home_score and raw_home_score > next_home_score\n      else raw_home_score\n\n    #(doc) Away team's score after the drive, with a scoreboard spike replaced by the previous possession's score.\n    despiked_away_score is\n      pick prev_away_score\n        when prev_away_score is not null and next_away_score is not null\n          and raw_away_score > prev_away_score and raw_away_score > next_away_score\n      else raw_away_score\n\n  calculate:\n    #(doc) The repaired home score on the previous possession, so the ledger can be held non-decreasing.\n    prev_despiked_home_score is lag(despiked_home_score) { partition_by: GameId, order_by: DriveNumber }\n\n    #(doc) The repaired away score on the previous possession.\n    prev_despiked_away_score is lag(despiked_away_score) { partition_by: GameId, order_by: DriveNumber }\n}\nextend {\n  primary_key: drive_id\n}\n\n#|(doc)\n  One row per drive (a single possession) in the 2025 and 2026 college football seasons, covering\n  the full Division I schedule: every FBS game and every FCS game. Each drive records who had the ball and who was\n  defending, when the possession started and ended on the game clock, where it started and\n  ended on the field, how many plays and yards it produced, how it ended (touchdown, field\n  goal, punt, interception, fumble, turnover on downs, end of half), and the score for both\n  teams before and after. Use it for drive efficiency, scoring rates, field position,\n  time of possession, three-and-outs, and drive-by-drive game charts. Joins to game-level\n  information on GameId.\n|#\nsource: drives_base is drives_deduped\ninclude {\n  public:\n\n    #(doc) Unique identifier for the drive. Formed from the game id plus the drive number within the game.\n    Id\n\n    #(doc) Identifier of the game this drive belongs to. Join key to the games data, whose Id column holds the same value.\n    GameId\n\n    #(index)\n    #(doc) Team with the ball on this drive, for example Alabama or Oregon.\n    Offense\n\n    #(index)\n    #(doc) Conference of the team with the ball, for example SEC or Big Ten. Missing for independents and for the occasional non-Division-I opponent.\n    OffenseConference\n\n    #(index)\n    #(doc) Team defending on this drive.\n    Defense\n\n    #(index)\n    #(doc) Conference of the defending team. Missing for independents and for the occasional non-Division-I opponent.\n    DefenseConference\n\n    #(doc) Sequence number of the possession within the game, starting at 1. Both teams' drives share one numbering, so drive 5 is the fifth possession of the game by either team.\n    DriveNumber\n\n    #(doc) True when the drive put points on the board for either team, including defensive returns and safeties.\n    Scoring\n\n    #(doc) Quarter the drive started in: 1 through 4 for regulation, 5 and above for overtime periods.\n    StartPeriod\n\n    #(doc) Field stripe the drive started on, 0 to 100, in absolute field coordinates: 0 is the goal line the away team attacks and 100 is the goal line the home team attacks. Use this to plot both teams' drives on one field.\n    StartYardline\n\n    #(doc) Distance in yards from the start of the drive to the end zone the offense is attacking. 75 means the offense started on its own 25.\n    StartYardsToGoal\n\n    #(doc) Minutes left on the game clock in the starting quarter when the drive began.\n    `StartTime Minutes`\n\n    #(doc) Seconds left on the game clock in the starting quarter when the drive began, on top of the minutes.\n    `StartTime Seconds`\n\n    #(doc) Quarter the drive ended in: 1 through 4 for regulation, 5 and above for overtime periods.\n    EndPeriod\n\n    #(doc) Field stripe the drive ended on, in the same absolute field coordinates as the start: 0 is the goal line the away team attacks and 100 is the goal line the home team attacks. A small number of rows fall outside 0 to 100 in the raw feed.\n    EndYardline\n\n    #(doc) Distance in yards from the end of the drive to the end zone the offense was attacking. 0 means the drive reached the end zone.\n    EndYardsToGoal\n\n    #(doc) Minutes left on the game clock in the ending quarter when the drive finished.\n    `EndTime Minutes`\n\n    #(doc) Seconds left on the game clock in the ending quarter when the drive finished, on top of the minutes.\n    `EndTime Seconds`\n\n    #(doc) Minutes of game clock the drive consumed.\n    `Elapsed Minutes`\n\n    #(doc) Seconds of game clock the drive consumed, on top of the minutes.\n    `Elapsed Seconds`\n\n    #(doc) Number of plays run on the drive.\n    Plays\n\n    #(doc) Net yards the offense gained on the drive. Can be negative when sacks and penalties lose ground.\n    Yards\n\n    #(index)\n    #(doc) How the drive ended, in the feed's own words: TD, FG, PUNT, DOWNS, INT, FUMBLE, MISSED FG, SF for safety, END OF HALF, END OF GAME, and returned-for-touchdown variants such as INT TD or PUNT RETURN TD where the defense scored.\n    DriveResult\n\n    #(doc) True when the team with the ball on this drive is the home team.\n    IsHomeOffense\n\n    #(doc) Score of the team with the ball, as it stood when the drive began.\n    StartOffenseScore\n\n    #(doc) Score of the defending team, as it stood when the drive began.\n    StartDefenseScore\n\n    #(doc) Score of the team with the ball, as it stood when the drive ended.\n    EndOffenseScore\n\n    #(doc) Score of the defending team, as it stood when the drive ended.\n    EndDefenseScore\n}\nextend {\n\n  primary_key: Id\n\n  #(doc) Possession counts for this drive: how many are left in the game, how many the team with the ball has left, and how many are left in this half.\n  join_one: possessions is drive_possession_context on Id = possessions.drive_id\n\n  // ---- How the drive ended -----------------------------------------\n  dimension:\n\n    #|(doc)\n      True when this possession is an overtime two-point conversion attempt rather than a\n      drive. From the third overtime on, the rules stop giving each team a possession from\n      the opponent's 25 and give it a single snap from the 3 instead, alternating until one\n      team converts and the other does not.\n\n      The feed has no name for these. It files all nine of them under the literal result\n      string \"Uncategorized\", every one a single play that gains nothing — and that pair of\n      facts, inside overtime, identifies them exactly. Period alone will not do it: the\n      feed skips a period in Missouri-Auburn and labels an ordinary 7-play touchdown drive\n      as the seventh period.\n    |#\n    is_overtime_conversion is\n      StartPeriod >= 5 and DriveResult = 'Uncategorized' and Plays <= 1 and Yards = 0\n\n    #(doc) True when an overtime two-point conversion attempt was good. Read from the feed's Scoring flag, which tracks these correctly — it reproduces the 53-51 finish of the nine-period South Dakota game exactly.\n    is_overtime_conversion_made is is_overtime_conversion and Scoring\n\n    #(index)\n    #(doc) How the drive ended, grouped into readable categories: Touchdown, Field goal, Punt, Missed field goal, Interception, Fumble, Turnover on downs, Safety, Defensive touchdown when the defense returned it for a score, End of period, Two-point conversion made and Two-point conversion failed for the alternating attempts from the third overtime on, and Uncategorized.\n    // WHO SCORED comes from the score columns, not from DriveResult.\n    // The feed's result string says how a possession ENDED, not who put\n    // points on the board: 78 drives labelled plain 'TD' are ones where\n    // the DEFENSE scored — Indiana's blocked punt return in the national\n    // championship is one of them — and another 152 are labelled 'PUNT',\n    // 27 'INT', 23 'FUMBLE'. Checking the scoreboard first catches all\n    // 231 of them. See defensive_points_scored for the guardrails.\n    result_category is\n      // Ahead of the scoreboard checks on purpose. A conversion attempt is\n      // identified by the SHAPE of the play — one snap, no gain, in\n      // overtime — and that holds even where the overtime score columns\n      // do not, which in this feed is most of the time.\n      pick 'Two-point conversion made' when is_overtime_conversion and Scoring\n      pick 'Two-point conversion failed' when is_overtime_conversion\n      pick 'Defensive touchdown' when defensive_points_scored >= 6\n      pick 'Safety' when defensive_points_scored = 2\n      pick 'End of period' when DriveResult ? 'END OF HALF' | 'END OF GAME' | 'END OF 4TH QUARTER' | 'END OF HALF TD' | 'END OF GAME TD' | 'KICKOFF'\n      pick 'Touchdown' when DriveResult = 'TD'\n      pick 'Field goal' when DriveResult = 'FG'\n      pick 'Punt' when DriveResult = 'PUNT'\n      pick 'Missed field goal' when DriveResult = 'MISSED FG'\n      pick 'Interception' when DriveResult = 'INT'\n      pick 'Fumble' when DriveResult = 'FUMBLE'\n      pick 'Turnover on downs' when DriveResult = 'DOWNS'\n      pick 'Safety' when DriveResult = 'SF'\n      else 'Uncategorized'\n\n    #(doc) Short label for how the drive ended, for drive charts: TD, FG, P for punt, FGA for a missed field goal attempt, Int, Fum, Downs, S for safety, Def TD, Half when the first half ran out, Game End when the game ran out, 2PT for a converted overtime two-point attempt and Miss for one that failed, and Other.\n    result_abbreviation is\n      // Short on purpose. These land in adjacent columns 30px apart, so a\n      // label wider than its column collides with its neighbour.\n      pick '2PT' when result_category = 'Two-point conversion made'\n      pick 'Miss' when result_category = 'Two-point conversion failed'\n      pick 'Def TD' when result_category = 'Defensive touchdown'\n      // the clock running out on the game reads very differently from it\n      // running out on the first half, so name them apart\n      pick 'Game End' when result_category = 'End of period' and possessions.drives_left_in_game = 1\n      pick 'Half' when result_category = 'End of period'\n      pick 'TD' when result_category = 'Touchdown'\n      pick 'FG' when result_category = 'Field goal'\n      pick 'P' when result_category = 'Punt'\n      pick 'FGA' when result_category = 'Missed field goal'\n      pick 'Int' when result_category = 'Interception'\n      pick 'Fum' when result_category = 'Fumble'\n      pick 'Downs' when result_category = 'Turnover on downs'\n      pick 'S' when result_category = 'Safety'\n      else 'Other'\n\n    #(doc) True when the offense scored a touchdown on this drive. False when the result string says TD but the points went to the defense.\n    is_touchdown is result_category = 'Touchdown'\n\n    #(doc) True when the drive ended in a made field goal by the offense. False for a kick that was blocked and returned.\n    is_field_goal is result_category = 'Field goal'\n\n    #(doc) True when the drive ended in a punt.\n    is_punt is DriveResult = 'PUNT'\n\n    #(doc) True when the offense turned the ball over by interception or fumble.\n    is_turnover is DriveResult ? 'INT' | 'FUMBLE' | 'INT TD' | 'FUMBLE RETURN TD' | 'FUMBLE TD'\n\n    #(doc) True when the offense handed the ball over on downs.\n    is_turnover_on_downs is DriveResult ? 'DOWNS' | 'DOWNS TD'\n\n    #(doc) True when the drive ended in points for the offense, by touchdown or field goal.\n    is_offensive_score is result_category ? 'Touchdown' | 'Field goal'\n\n    #(doc) True when the drive gave up points to the defense, by return touchdown, blocked kick, or safety.\n    is_defensive_score is defensive_points_scored > 0\n\n    #(doc) True when the drive ran three plays or fewer and ended in a punt, the classic three-and-out.\n    is_three_and_out is Plays <= 3 and DriveResult = 'PUNT'\n\n    #(doc) True when the drive simply ran out of clock at the end of a half, a quarter, or the game.\n    is_clock_expiration is result_category = 'End of period'\n\n    #(doc) True when the drive gained 40 yards or more.\n    is_explosive_drive is Yards >= 40\n\n    #|(doc)\n      True when the drive was a quality possession in the Eckel-rate sense: it scored a\n      touchdown, or it reached the opponent's 35 having gained at least ten yards. Eckel rate\n      proper counts a first down inside the opponent's 40, which needs play-by-play; ending\n      at the 35 or closer after a ten-yard gain is the drive-level stand-in.\n    |#\n    is_eckel_drive is is_touchdown or (EndYardsToGoal <= 35 and Yards >= 10)\n\n  // ---- Scoring -----------------------------------------------------\n  dimension:\n\n    #|(doc)\n      Points the offense scored on this drive, taken from the score before and after so that\n      extra points and two-point conversions are counted. On the 0.8% of drives where the\n      feed's score columns skip an intervening score and produce a value no single possession\n      can produce (outside 0 to 8), it falls back to the drive's result: 7 for a touchdown,\n      3 for a made field goal, 0 otherwise. Without that repair those 325 rows contribute 6%\n      of the season's points and inflate every scoring rate.\n    |#\n    drive_points is\n      pick EndOffenseScore - StartOffenseScore\n        when EndOffenseScore - StartOffenseScore >= 0 and EndOffenseScore - StartOffenseScore <= 8\n      pick 7 when DriveResult = 'TD'\n      pick 3 when DriveResult = 'FG'\n      else 0\n\n    #(doc) True when the feed's own result string already says the defense scored, for example INT TD, PUNT RETURN TD, or SF.\n    is_named_defensive_score is\n      DriveResult ? 'INT TD' | 'FUMBLE RETURN TD' | 'FUMBLE TD' | 'PUNT TD' | 'PUNT RETURN TD'\n        | 'MISSED FG TD' | 'DOWNS TD' | 'END OF HALF TD' | 'END OF GAME TD' | 'SF'\n\n    #|(doc)\n      True when this drive's closing scoreboard matches the next drive's opening one, with the\n      two teams' columns swapped if possession changed hands. Roughly 7% of consecutive drives\n      disagree, which is the feed's score columns lagging a possession — so this is what\n      separates a real defensive score from a column that simply jumped.\n    |#\n    scoreboard_agrees_with_next_drive is\n      possessions.next_offense is null\n      or (possessions.next_offense != Offense\n          and EndOffenseScore = possessions.next_start_defense_score\n          and EndDefenseScore = possessions.next_start_offense_score)\n      or (possessions.next_offense = Offense\n          and EndOffenseScore = possessions.next_start_offense_score\n          and EndDefenseScore = possessions.next_start_defense_score)\n\n    #|(doc)\n      Points the defense scored on this possession, from return touchdowns, blocked kicks\n      returned, and safeties. Read from the scoreboard rather than the result string, which\n      says how a possession ended and not who scored.\n\n      Two guardrails, both earned the hard way. A defense cannot score 3, so only a move of\n      6 to 8 counts as a return touchdown and only 2 as a safety. And a scoreboard move the\n      feed does not corroborate is not believed: of the 231 drives where the defensive column\n      jumps by a touchdown without the result string saying so, only 122 line up with the next\n      drive's opening score — the rest are the columns lagging, and counting them would invent\n      about a hundred defensive touchdowns.\n    |#\n    defensive_points_scored is\n      pick EndDefenseScore - StartDefenseScore\n        when ((EndDefenseScore - StartDefenseScore >= 6 and EndDefenseScore - StartDefenseScore <= 8)\n              or EndDefenseScore - StartDefenseScore = 2)\n         and (is_named_defensive_score or scoreboard_agrees_with_next_drive)\n      pick 2 when DriveResult = 'SF'\n      pick 7 when is_named_defensive_score\n      else 0\n\n    #(doc) Kept as an alias of the points the defense scored on this possession.\n    defense_points_allowed is defensive_points_scored\n\n    #(doc) How the defense scored, when it did: Punt return or block, Interception return, Fumble return, Blocked kick return, Safety, or Return touchdown when the feed does not say. Empty when the defense did not score.\n    defensive_score_type is\n      pick null when defensive_points_scored = 0\n      pick 'Safety' when defensive_points_scored = 2\n      pick 'Punt return or block' when DriveResult ? 'PUNT' | 'PUNT TD' | 'PUNT RETURN TD'\n      pick 'Interception return' when DriveResult ? 'INT' | 'INT TD'\n      pick 'Fumble return' when DriveResult ? 'FUMBLE' | 'FUMBLE TD' | 'FUMBLE RETURN TD'\n      pick 'Blocked kick return' when DriveResult ? 'FG' | 'MISSED FG' | 'MISSED FG TD'\n      else 'Return touchdown'\n\n    #(doc) Home team's score once the drive was over, with the feed's scoreboard spikes repaired and the running total held non-decreasing.\n    home_score_after is\n      greatest(\n        possessions.despiked_home_score,\n        possessions.prev_despiked_home_score ?? possessions.despiked_home_score\n      )\n\n    #(doc) Away team's score once the drive was over, with the feed's scoreboard spikes repaired and the running total held non-decreasing.\n    away_score_after is\n      greatest(\n        possessions.despiked_away_score,\n        possessions.prev_despiked_away_score ?? possessions.despiked_away_score\n      )\n\n  // ---- Field position and clock ------------------------------------\n  dimension:\n\n    #(doc) Yards from the offense's own goal line where the drive started. 25 means the drive started on the offense's own 25.\n    start_field_position is 100 - StartYardsToGoal\n\n    #(doc) Yards from the offense's own goal line where the drive ended.\n    end_field_position is 100 - EndYardsToGoal\n\n    #(doc) Net yards of field position the drive gained, measured from where it started to where it ended.\n    field_position_gained is StartYardsToGoal - EndYardsToGoal\n\n    #(doc) Starting field position rounded into five-yard bands and labelled with the middle of the band, so 27.5 covers drives starting between the offense's own 25 and its own 29. Use it to plot field position against scoring without the noise of single-yard buckets.\n    start_field_position_band is floor((100 - StartYardsToGoal) / 5) * 5 + 2.5\n\n    #(doc) Where the drive started, in bands: Deep in own territory inside the own 10, Own territory to the own 39, Midfield from the own 40 to the opponent 40, and Plus territory inside the opponent 40.\n    start_field_position_zone is\n      pick 'Deep in own territory' when StartYardsToGoal >= 91\n      pick 'Own territory' when StartYardsToGoal >= 61\n      pick 'Midfield' when StartYardsToGoal >= 40\n      else 'Plus territory'\n\n    #(doc) True when the drive reached the opponent's 20-yard line or closer.\n    reached_red_zone is EndYardsToGoal <= 20\n\n    #(doc) Quarter the drive started in, written out: 1st, 2nd, 3rd, 4th, or OT for any overtime period.\n    quarter_label is\n      pick '1st' when StartPeriod = 1\n      pick '2nd' when StartPeriod = 2\n      pick '3rd' when StartPeriod = 3\n      pick '4th' when StartPeriod = 4\n      pick 'OT' when StartPeriod >= 5\n      else 'Unknown'\n\n    #(doc) Half the drive started in: 1st half, 2nd half, or Overtime.\n    half_label is\n      pick '1st half' when StartPeriod <= 2\n      pick '2nd half' when StartPeriod = 3 or StartPeriod = 4\n      pick 'Overtime' when StartPeriod >= 5\n      else 'Unknown'\n\n    #(doc) Seconds of game clock the drive consumed, its time of possession.\n    time_of_possession_seconds is `Elapsed Minutes` * 60 + `Elapsed Seconds`\n\n    #(doc) Seconds left in the quarter when the drive began.\n    clock_seconds_at_start is `StartTime Minutes` * 60 + `StartTime Seconds`\n\n    #(doc) Yards gained per play on the drive.\n    yards_per_play_on_drive is Yards / nullif(Plays, 0)\n\n  // ---- Field goal attempts -----------------------------------------\n  //  The feed has no kick distance, but a drive that ends in a field\n  //  goal ends where the ball was snapped from, so the attempt is\n  //  EndYardsToGoal + 17 (10 yards of end zone + a 7-yard hold).\n  dimension:\n\n    #(doc) True when the drive ended with a field goal attempt, made or missed.\n    is_field_goal_attempt is DriveResult ? 'FG' | 'MISSED FG' | 'MISSED FG TD'\n\n    #(doc) Length of the field goal attempt in yards, counted from the holder's spot through the back of the end zone: the ball's distance to the goal line plus 17. Empty on drives that did not end in a kick.\n    field_goal_distance is\n      pick EndYardsToGoal + 17 when is_field_goal_attempt\n      else null\n\n    #(doc) Field goal distance rounded into five-yard bands and labelled with the middle of the band, so 42.5 covers attempts from 40 to 44 yards. Use it when comparing kicking curves for groups smaller than the whole league, where single-yard buckets are too thin.\n    field_goal_distance_band is\n      pick floor((EndYardsToGoal + 17) / 5) * 5 + 2.5 when is_field_goal_attempt\n      else null\n\n    #(doc) Range band of the field goal attempt: Chip shot under 30 yards, Short 30 to 39, Medium 40 to 49, Long 50 to 59, and Very long at 60 or more.\n    field_goal_range is\n      pick null when not is_field_goal_attempt\n      pick 'Chip shot' when EndYardsToGoal + 17 < 30\n      pick 'Short' when EndYardsToGoal + 17 < 40\n      pick 'Medium' when EndYardsToGoal + 17 < 50\n      pick 'Long' when EndYardsToGoal + 17 < 60\n      else 'Very long'\n\n  // ---- Chart-ready geometry ----------------------------------------\n  //  Absolute field coordinates, cleaned so a drive chart can be drawn\n  //  directly from them: both teams plot on one 0-100 axis, 0 is the\n  //  goal line the away team attacks and 100 the goal line the home\n  //  team attacks.\n  dimension:\n\n    #(doc) Field stripe the drive started on for charting, in absolute field coordinates from 0 to 100, clamped into the field of play.\n    chart_start_yardline is least(greatest(StartYardline, 0), 100)\n\n    #(doc) Field stripe the drive ended on for charting, in absolute field coordinates from 0 to 100. Touchdown drives are drawn all the way to the goal line the offense was attacking, and stray values from the raw feed are clamped into the field of play.\n    chart_end_yardline is\n      pick 100 when is_touchdown and IsHomeOffense\n      pick 0 when is_touchdown and not IsHomeOffense\n      else least(greatest(EndYardline, 0), 100)\n\n    #(doc) Direction the offense was moving on the field chart: up toward 100 for the home team, down toward 0 for the away team.\n    chart_direction is\n      pick 'up' when IsHomeOffense\n      else 'down'\n\n  // ---- Garbage time --------------------------------------------------\n  //  BCFtoys' garbage-possession rules, implemented as stated at\n  //  https://bcftoys.com/whiteboard/. The idea: a possession is garbage\n  //  when neither team is still playing to win it — the clock is being\n  //  run out, or the score is already out of reach.\n  //\n  //  A note on \"runs out the clock\": the feed's EndTime column is 0:00\n  //  on only ~64% of the drives it labels END OF HALF or END OF GAME, so\n  //  it cannot carry these rules. What identifies a clock-killing\n  //  possession reliably is the pair of facts BCFtoys itself names —\n  //  it is the LAST possession of the half or game, and it produced no\n  //  turnover, no score, and no field goal attempt. That is what\n  //  clock_ran_out tests, and it correctly picks up the 198 end-of-game\n  //  kneel-downs the feed leaves as \"Uncategorized\".\n  dimension:\n\n    #(doc) Score margin from the point of view of the team with the ball, as it stood when the drive began. Positive means the offense was ahead.\n    margin_at_drive_start is StartOffenseScore - StartDefenseScore\n\n    #(doc) Points the trailing team was behind by when the drive began. Zero when the game was tied.\n    deficit_at_drive_start is abs(StartOffenseScore - StartDefenseScore)\n\n    #(doc) Number of possessions the team with the ball has left in the game, counting this one.\n    offense_possessions_left is possessions.offense_possessions_left\n\n    #(doc) Number of possessions the defending team has left in the game after this one.\n    defense_possessions_left is possessions.drives_left_in_game - possessions.offense_possessions_left\n\n    #(doc) Number of possessions the trailing team has left to erase the deficit. Empty when the game is tied.\n    losing_team_possessions_left is\n      pick possessions.offense_possessions_left when margin_at_drive_start < 0\n      pick possessions.drives_left_in_game - possessions.offense_possessions_left when margin_at_drive_start > 0\n      else null\n\n    #(doc) True when this is the last possession of the game.\n    ends_game is possessions.drives_left_in_game = 1\n\n    #(doc) True when this is the last possession of the first half.\n    ends_first_half is possessions.period_group = 1 and possessions.drives_left_in_period_group = 1\n\n    #(doc) True when this is the last possession of regulation, the end of the second half.\n    ends_regulation is possessions.period_group = 2 and possessions.drives_left_in_period_group = 1\n\n    #(doc) True when the possession simply ran out of clock: no turnover, no points for either team, and no field goal attempt.\n    clock_ran_out is\n      not is_turnover\n      and not is_turnover_on_downs\n      and not is_field_goal_attempt\n      and EndOffenseScore = StartOffenseScore\n      and EndDefenseScore = StartDefenseScore\n\n    #(doc) Garbage rule one: a possession of two plays or fewer that runs out the clock to end the first half, or to end regulation with the score tied, without a turnover, a score, or a field goal attempt.\n    is_garbage_end_of_half is\n      Plays <= 2 and clock_ran_out\n      and (ends_first_half or (ends_regulation and margin_at_drive_start = 0))\n\n    #(doc) Garbage rule two: a second-half possession where the game is already out of reach, because eight points times the trailing team's remaining possessions, plus one, is still less than the deficit.\n    is_garbage_out_of_reach is\n      StartPeriod >= 3\n      and margin_at_drive_start != 0\n      and 8 * losing_team_possessions_left + 1 < deficit_at_drive_start\n\n    #(doc) Garbage rule three: a possession of two plays or fewer by a team trailing by more than eight that runs out the clock to end the game.\n    is_garbage_trailing_kneel is\n      Plays <= 2 and ends_game and clock_ran_out and margin_at_drive_start < -8\n\n    #(doc) Garbage rule four: the victory formation. A possession by the team ahead by eight points or fewer that runs out the clock to end the game.\n    is_garbage_victory_formation is\n      ends_game and clock_ran_out\n      and margin_at_drive_start > 0 and margin_at_drive_start <= 8\n\n    #|(doc)\n      True when the possession is garbage time — neither team is still playing to win it.\n      Covers all four of BCFtoys' rules: a kneel-down to end the first half or a tied\n      regulation, a second-half possession with the game already out of reach, a kneel-down\n      by a team trailing by more than eight, and the winning team's victory formation.\n      About 16% of the season's drives, and half of all fourth-quarter possessions.\n    |#\n    is_garbage_possession is\n      (is_garbage_end_of_half\n        or is_garbage_out_of_reach\n        or is_garbage_trailing_kneel\n        or is_garbage_victory_formation) ?? false\n\n    #(index)\n    #(doc) Why the possession counts as garbage time: End of half kneel-down, Victory formation, Trailing kneel-down, or Out of reach. Competitive for everything else.\n    // Named rules first, then the catch-all: most end-of-game kneel-downs\n    // also satisfy the out-of-reach rule, and calling one a kneel-down\n    // says more than calling it out of reach.\n    garbage_reason is\n      pick 'End of half kneel-down' when is_garbage_end_of_half\n      pick 'Victory formation' when is_garbage_victory_formation\n      pick 'Trailing kneel-down' when is_garbage_trailing_kneel\n      pick 'Out of reach' when is_garbage_out_of_reach\n      else 'Competitive'\n\n  // ---- Measures ----------------------------------------------------\n  measure:\n\n    #(doc) Number of drives.\n    drive_count is count()\n\n    #(doc) Number of games the drives come from.\n    game_count is count(GameId)\n\n    #(doc) Total plays run.\n    play_count is sum(Plays)\n\n    #(doc) Total net yards gained.\n    total_yards is sum(Yards)\n\n    #(doc) Total points scored by the offense on these drives.\n    total_points is sum(drive_points)\n\n    #(doc) Average points the offense scores per drive, the standard measure of drive efficiency.\n    points_per_drive is sum(drive_points) / nullif(count(), 0)\n\n    #(doc) Average net yards gained per drive.\n    yards_per_drive is sum(Yards) / nullif(count(), 0)\n\n    #(doc) Average number of plays per drive.\n    plays_per_drive is sum(Plays) / nullif(count(), 0)\n\n    #(doc) Average yards gained per play.\n    yards_per_play is sum(Yards) / nullif(sum(Plays), 0)\n\n    #(doc) Share of drives that ended in points for either team.\n    # percent\n    scoring_drive_rate is count() { where: Scoring } / nullif(count(), 0)\n\n    #(doc) Share of drives that ended in a touchdown by the offense.\n    # percent\n    touchdown_rate is count() { where: is_touchdown } / nullif(count(), 0)\n\n    #(doc) Share of drives that ended in a made field goal.\n    # percent\n    field_goal_rate is count() { where: is_field_goal } / nullif(count(), 0)\n\n    #(doc) Share of drives that ended in a punt.\n    # percent\n    punt_rate is count() { where: is_punt } / nullif(count(), 0)\n\n    #(doc) Share of drives that ended in an interception or a lost fumble.\n    # percent\n    turnover_rate is count() { where: is_turnover } / nullif(count(), 0)\n\n    #(doc) Share of drives that ended with three plays or fewer and a punt.\n    # percent\n    three_and_out_rate is count() { where: is_three_and_out } / nullif(count(), 0)\n\n    #(doc) Share of drives that reached the opponent's 20-yard line or closer.\n    # percent\n    red_zone_rate is count() { where: reached_red_zone } / nullif(count(), 0)\n\n    #(doc) Share of drives that gained 40 yards or more.\n    # percent\n    explosive_drive_rate is count() { where: is_explosive_drive } / nullif(count(), 0)\n\n    #(doc) Eckel rate: share of drives that were quality possessions — a touchdown, or reaching the opponent's 35 after gaining at least ten yards. Measures how often an offense puts itself in position to score, separately from whether the kicker or the red zone finishes it. About 48% for Power Four offenses in 2025.\n    # percent\n    eckel_rate is count() { where: is_eckel_drive } / nullif(count(), 0)\n\n    #(doc) Number of drives that ended in a touchdown.\n    touchdown_count is count() { where: is_touchdown }\n\n    #(doc) Number of drives that ended in a giveaway by interception or fumble.\n    turnover_count is count() { where: is_turnover }\n\n    #(doc) Number of times the defense scored on a drive, by return touchdown or safety.\n    defensive_score_count is count() { where: is_defensive_score }\n\n    #(doc) Average distance to the end zone at the start of a drive. Lower is better field position.\n    avg_start_yards_to_goal is avg(StartYardsToGoal)\n\n    #(doc) Average yard line a drive starts on, measured from the offense's own goal line. Higher is better field position.\n    avg_start_field_position is avg(start_field_position)\n\n    #(doc) Total time of possession across these drives, in minutes.\n    time_of_possession_minutes is sum(time_of_possession_seconds) / 60\n\n    #(doc) Average length of a drive in seconds of game clock.\n    avg_drive_seconds is avg(time_of_possession_seconds)\n\n    #(doc) Longest drive by yards gained.\n    longest_drive_yards is max(Yards)\n\n    #(doc) Number of garbage-time possessions, where neither team is still playing to win.\n    garbage_drive_count is count() { where: is_garbage_possession }\n\n    #(doc) Share of possessions that are garbage time.\n    # percent\n    garbage_drive_rate is count() { where: is_garbage_possession } / nullif(count(), 0)\n\n    #(doc) Number of possessions that were still competitive.\n    competitive_drive_count is count() { where: not is_garbage_possession }\n\n    #(doc) Average points scored per possession, counting only competitive possessions. The scoring rate with garbage time thrown out.\n    competitive_points_per_drive is\n      sum(drive_points) { where: not is_garbage_possession }\n      / nullif(count() { where: not is_garbage_possession }, 0)\n\n    #(doc) Number of field goal attempts, made and missed.\n    field_goal_attempts is count() { where: is_field_goal_attempt }\n\n    #(doc) Share of field goal attempts that were made.\n    # percent\n    field_goal_make_rate is count() { where: is_field_goal } / nullif(count() { where: is_field_goal_attempt }, 0)\n\n    #(doc) Number of field goal attempts that were made.\n    field_goal_makes is count() { where: is_field_goal }\n\n    #(doc) Average points scored per field goal attempt: three points for a make, none for a miss, so it is the make rate times three. This is the expected value of taking the kick. Counted from the result of the kick rather than the score columns, which are out of sync on about 2% of kicking drives.\n    expected_points_per_fg_attempt is 3.0 * count() { where: is_field_goal } / nullif(count() { where: is_field_goal_attempt }, 0)\n\n    #(doc) Average length of a field goal attempt in yards.\n    avg_field_goal_distance is avg(field_goal_distance)\n\n  // ---- Views -------------------------------------------------------\n\n  #(doc) Offensive drive efficiency by team, ranked by points per drive. The core offensive leaderboard.\n  view: offense_leaderboard is {\n    group_by: team is Offense\n    aggregate: drive_count, points_per_drive, yards_per_drive, touchdown_rate, three_and_out_rate, turnover_rate, avg_start_field_position\n    having: drive_count > 100\n    order_by: points_per_drive desc\n  }\n\n  #(doc) Defensive drive efficiency by team, ranked by fewest points allowed per drive. The core defensive leaderboard.\n  view: defense_leaderboard is {\n    group_by: team is Defense\n    aggregate: drive_count, points_per_drive, yards_per_drive, touchdown_rate, three_and_out_rate, turnover_rate\n    having: drive_count > 100\n    order_by: points_per_drive asc\n  }\n\n  #(doc) How drives end across the season, most common outcome first.\n  view: by_result is {\n    group_by: result_category\n    aggregate: drive_count, yards_per_drive, plays_per_drive, avg_drive_seconds\n    order_by: drive_count desc\n  }\n\n  #(doc) Drive efficiency by quarter, showing how offenses change through a game.\n  view: by_quarter is {\n    group_by: quarter_label\n    aggregate: drive_count, points_per_drive, yards_per_drive, three_and_out_rate, scoring_drive_rate\n    order_by: quarter_label\n  }\n\n  #(doc) How much starting field position is worth: drive efficiency by where the drive began.\n  view: by_start_field_position is {\n    group_by: start_field_position_zone\n    aggregate: drive_count, points_per_drive, touchdown_rate, punt_rate, yards_per_drive\n    order_by: drive_count desc\n  }\n\n  #(doc) Offensive drive efficiency by conference, best scoring conference first.\n  view: by_conference is {\n    where: OffenseConference is not null\n    group_by: conference is OffenseConference\n    aggregate: drive_count, points_per_drive, yards_per_drive, touchdown_rate, turnover_rate\n    order_by: points_per_drive desc\n  }\n\n  #(doc) Every drive of a game in order, with field position, result and the score afterwards. The drive-by-drive game log.\n  view: drive_log is {\n    group_by:\n      DriveNumber\n      Offense\n      quarter_label\n      start_field_position\n      Plays\n      Yards\n      result_category\n      home_score_after\n      away_score_after\n    order_by: DriveNumber\n  }\n\n  #(doc) The longest scoring drives of the season, by yards gained.\n  view: longest_scoring_drives is {\n    where: is_offensive_score\n    group_by: Offense, Defense, Yards, Plays, result_category\n    order_by: Yards desc\n    limit: 25\n  }\n\n  #|(doc)\n    Expected points of a field goal attempt by kick distance: for every attempt length,\n    how many points the attempt is worth on average (three times the make rate). The\n    scoring curve kickers are judged against, and the input to any go-for-it decision.\n  |#\n  view: field_goal_expected_points is {\n    // 70 yards is past the longest kick anyone attempts; longer values\n    // are the handful of bad end-of-drive spots in the raw feed\n    where: is_field_goal_attempt and field_goal_distance >= 17 and field_goal_distance <= 70\n    group_by: field_goal_distance\n    aggregate:\n      field_goal_attempts\n      field_goal_makes\n      expected_points_per_fg_attempt\n      field_goal_make_rate\n    order_by: field_goal_distance\n  }\n\n  #|(doc)\n    What a yard of field position is worth: average points scored per drive by the yard\n    line the drive started on, measured from the offense's own goal line. Rises steadily\n    from about 1.2 points starting on your own 1 to about 4 points starting inside the\n    opponent's 35.\n  |#\n  view: points_by_start_yardline is {\n    group_by: start_field_position\n    aggregate: drive_count, points_per_drive, touchdown_rate\n    order_by: start_field_position\n  }\n\n  #(doc) How much of the season is garbage time, broken out by the rule that classified each possession, and how differently those possessions play.\n  view: garbage_time_breakdown is {\n    group_by: garbage_reason\n    aggregate: drive_count, points_per_drive, yards_per_drive, plays_per_drive\n    order_by: drive_count desc\n  }\n\n  #(doc) Garbage time by quarter — where in a game the possessions that no longer matter actually happen.\n  view: garbage_time_by_quarter is {\n    group_by: quarter_label\n    aggregate: drive_count, garbage_drive_count, garbage_drive_rate\n    order_by: quarter_label\n  }\n\n  #(doc) Teams whose drives most often end in a three-and-out punt, worst offenses first.\n  view: worst_three_and_out_offenses is {\n    group_by: team is Offense\n    aggregate: drive_count, three_and_out_rate, points_per_drive\n    having: drive_count > 100\n    order_by: three_and_out_rate desc\n    limit: 25\n  }\n}\n","file:///games.malloy":"##! experimental.access_modifiers\n\nimport \"raw.malloy\"\n\n// =====================================================================\n//  GAMES — one row per college football game, 2025 and 2026 seasons\n//\n//  Source: games_raw (raw.malloy), the CollegeFootballData (CFBD) /games\n//  feed read from huggingface.co/datasets/24601p/cfb-data, one parquet\n//  file per season.\n//\n//  GRAIN: one row per game. `Id` is unique across both seasons.\n//  COVERAGE: 2025 is complete (3,831 games, August 2025 through the\n//  January 2026 championship). 2026 carries the whole schedule, with\n//  scores filling in as games are played. All divisions (fbs, fcs, ii,\n//  iii); drive detail exists only for Division I games.\n//\n//  This file is adapted from ../games.malloy, the 2025-only model. The\n//  additions are the season and week labels and the thrill index.\n//\n//  TIME ZONE: the feed publishes kickoff in UTC; StartDate was written to\n//  parquet as a naive US/Pacific local timestamp, so a late Saturday-night\n//  Eastern kickoff still lands on the Saturday calendar date.\n// =====================================================================\n\n#|(doc)\n  One row per college football game in the 2025 and 2026 seasons, across every division: FBS, FCS, Division II\n  and Division III. Each game carries the final score, venue and announced attendance,\n  the conference and division of both teams, pregame and postgame Elo ratings, postgame\n  win probability, an excitement rating, and College Football Playoff bracket details\n  for playoff games. Use it for schedules, results, margins, attendance, rankings-style\n  Elo movement, and as the game-level context for drive-by-drive data, which joins on\n  game id.\n|#\nsource: games_base is games_raw\ninclude {\n  public:\n\n    #(doc) Unique identifier for the game. Join key to the drives data, whose GameId column holds the same value.\n    Id\n\n    #(doc) Season year the game belongs to: 2025 or 2026. A season's bowls and playoff games played in January still belong to the season that started in August.\n    Season\n\n    #(doc) Week of the season the game was played in, numbered within the season type. Regular-season weeks run 1 to 16; postseason bowl and playoff games carry their own week numbers.\n    `Week`\n\n    #(index)\n    #(doc) Portion of the season: regular for the regular season, postseason for bowls and College Football Playoff games.\n    SeasonType\n\n    #(doc) Scheduled kickoff date and time, expressed in US Pacific local time.\n    StartDate\n\n    #(doc) True when the kickoff time had not been announced yet, so only the date is meaningful.\n    StartTimeTBD\n\n    #(doc) True when the game has been played and the final score is official.\n    Completed\n\n    #(doc) True when the game was played at a neutral venue rather than either team's own stadium. Bowl games, playoff games and kickoff classics are typically neutral site.\n    NeutralSite\n\n    #(doc) True when both teams belong to the same conference, so the result counts in the conference standings.\n    ConferenceGame\n\n    #(doc) Announced attendance for the game, in people. Missing for many games, especially at the Division II and Division III level.\n    Attendance\n\n    #(doc) Unique identifier of the stadium the game was played in.\n    VenueId\n\n    #(index)\n    #(doc) Name of the stadium the game was played in, for example Bryant-Denny Stadium.\n    Venue\n\n    #(doc) Unique identifier of the home team.\n    HomeId\n\n    #(index)\n    #(doc) Name of the home team, for example Alabama or Ohio State.\n    HomeTeam\n\n    #(index)\n    #(doc) Division the home team competes in: fbs, fcs, ii for Division II, or iii for Division III.\n    HomeClassification\n\n    #(index)\n    #(doc) Conference the home team belongs to, for example SEC, Big Ten, ACC or Big 12. Missing for independents and some non-Division-I programs.\n    HomeConference\n\n    #(doc) Final points scored by the home team. Missing until the game has been played.\n    HomePoints\n\n    #(doc) Points the home team scored in each period, as a comma-separated list in order, for example 7,10,0,14 for the four quarters.\n    HomeLineScores\n\n    #(doc) Postgame win expectancy for the home team: how likely it was to win given how the game was played, from 0 to 1. It pairs with the away value to sum to 1 and is not the result itself — a team can lose a game it was 90% likely to win. Matches the actual winner in about 90% of games.\n    HomePostgameWinProbability\n\n    #(doc) Home team's Elo power rating going into the game. Higher is stronger; roughly 1500 is average.\n    HomePregameElo\n\n    #(doc) Home team's Elo power rating after the game, reflecting the result. Higher is stronger.\n    HomePostgameElo\n\n    #(doc) Unique identifier of the away team.\n    AwayId\n\n    #(index)\n    #(doc) Name of the away team, for example Michigan or Texas.\n    AwayTeam\n\n    #(index)\n    #(doc) Division the away team competes in: fbs, fcs, ii for Division II, or iii for Division III.\n    AwayClassification\n\n    #(index)\n    #(doc) Conference the away team belongs to, for example SEC, Big Ten, ACC or Big 12. Missing for independents and some non-Division-I programs.\n    AwayConference\n\n    #(doc) Final points scored by the away team. Missing until the game has been played.\n    AwayPoints\n\n    #(doc) Points the away team scored in each period, as a comma-separated list in order, for example 3,7,7,0 for the four quarters.\n    AwayLineScores\n\n    #(doc) Postgame win expectancy for the away team: how likely it was to win given how the game was played, from 0 to 1. It pairs with the home value to sum to 1 and is not the result itself.\n    AwayPostgameWinProbability\n\n    #(doc) Away team's Elo power rating going into the game. Higher is stronger; roughly 1500 is average.\n    AwayPregameElo\n\n    #(doc) Away team's Elo power rating after the game, reflecting the result. Higher is stronger.\n    AwayPostgameElo\n\n    #(doc) Excitement rating for the game, built from how much and how often the win probability swung. Typical games rate near 4; the wildest finishes rate above 8.\n    ExcitementIndex\n\n    #(doc) Link to the game's video highlights, when one is published.\n    Highlights\n\n    #(doc) Free-text note about the game, usually the name of a kickoff event or a special circumstance, for example Aer Lingus College Football Classic.\n    Notes\n\n    #(index)\n    #(doc) Postseason competition the game belongs to. cfp for the College Football Playoff; missing for regular-season and ordinary bowl games.\n    `Playoff Competition`\n\n    #(doc) Playoff bracket format in force for the season, for example twelve_team_2025.\n    `Playoff Format`\n\n    #(index)\n    #(doc) Playoff round in machine form: first_round, quarterfinal, semifinal or championship.\n    `Playoff Round`\n\n    #(index)\n    #(doc) Playoff round in readable form: First Round, Quarterfinal, Semifinal or National Championship.\n    `Playoff RoundName`\n\n    #(doc) Slot the game occupies in the playoff bracket, for example QF1 for the first quarterfinal or CH for the championship.\n    `Playoff BracketSlot`\n\n    #(doc) Playoff seed of the home team, 1 through 12. Missing outside the playoff.\n    `Playoff HomeSeed`\n\n    #(doc) Playoff seed of the away team, 1 through 12. Missing outside the playoff.\n    `Playoff AwaySeed`\n\n    #(index)\n    #(doc) Bowl the playoff game was hosted by, for example Rose Bowl, Sugar Bowl or College Football Playoff National Championship.\n    `Playoff BowlName`\n}\nextend {\n\n  primary_key: Id\n\n  // ---- Derived game attributes -------------------------------------\n  dimension:\n\n    #(doc) Calendar date the game kicked off, in US Pacific local time.\n    game_date is StartDate::date\n\n    #(doc) Matchup in away-at-home form, for example Michigan at Ohio State.\n    matchup is concat(AwayTeam, ' at ', HomeTeam)\n\n    #(doc) Final score written out, for example Ohio State 30, Michigan 24, with the winner first. Empty until the game is played.\n    final_score is\n      pick concat(HomeTeam, ' ', HomePoints::string, ', ', AwayTeam, ' ', AwayPoints::string) when HomePoints >= AwayPoints\n      else concat(AwayTeam, ' ', AwayPoints::string, ', ', HomeTeam, ' ', HomePoints::string)\n\n    #(doc) Team that won the game. Empty for ties and for games that have not been played.\n    winner is\n      pick HomeTeam when HomePoints > AwayPoints\n      pick AwayTeam when AwayPoints > HomePoints\n      else null\n\n    #(doc) Team that lost the game. Empty for ties and for games that have not been played.\n    loser is\n      pick AwayTeam when HomePoints > AwayPoints\n      pick HomeTeam when AwayPoints > HomePoints\n      else null\n\n    #(doc) True when the home team won.\n    home_win is HomePoints > AwayPoints\n\n    #(doc) Combined points scored by both teams.\n    total_points is HomePoints + AwayPoints\n\n    #(doc) Home points minus away points. Positive when the home team won, negative when the away team won.\n    point_margin is HomePoints - AwayPoints\n\n    #(doc) Winning margin in points, regardless of which team won.\n    victory_margin is abs(HomePoints - AwayPoints)\n\n    #(doc) How close the game was: One-score game for a margin of 8 or less, Two-score game for 9 to 16, Comfortable for 17 to 27, and Blowout for 28 or more.\n    margin_bucket is\n      pick 'One-score game' when abs(HomePoints - AwayPoints) <= 8\n      pick 'Two-score game' when abs(HomePoints - AwayPoints) <= 16\n      pick 'Comfortable' when abs(HomePoints - AwayPoints) <= 27\n      else 'Blowout'\n\n    #(doc) Division matchup, for example fbs vs fbs or fbs vs fcs, using the two teams' divisions.\n    classification_matchup is concat(HomeClassification, ' vs ', AwayClassification)\n\n    #(doc) True when both teams are FBS programs, the top division of college football.\n    is_fbs_matchup is HomeClassification = 'fbs' and AwayClassification = 'fbs'\n\n    #(doc) True when the game is part of the College Football Playoff bracket.\n    is_playoff_game is `Playoff Competition` is not null\n\n    #(doc) Home team's Elo rating minus the away team's Elo rating before kickoff. Positive means the home team was the stronger team on paper.\n    pregame_elo_edge is HomePregameElo - AwayPregameElo\n\n    #(doc) Team the pregame Elo ratings favored, before any home-field adjustment.\n    elo_favorite is\n      pick HomeTeam when HomePregameElo > AwayPregameElo\n      pick AwayTeam when AwayPregameElo > HomePregameElo\n      else null\n\n    #(doc) True when the team with the lower pregame Elo rating won the game.\n    is_elo_upset is\n      (HomePoints > AwayPoints and HomePregameElo < AwayPregameElo)\n      or (AwayPoints > HomePoints and AwayPregameElo < HomePregameElo)\n\n    #(doc) Points of Elo rating the home team gained from the game. Negative when the home team lost ground.\n    home_elo_change is HomePostgameElo - HomePregameElo\n\n    #(doc) Points of Elo rating the away team gained from the game. Negative when the away team lost ground.\n    away_elo_change is AwayPostgameElo - AwayPregameElo\n\n    #(doc) How dramatic the game was, from its excitement rating: Instant classic above 8, Thriller above 6, Competitive above 4, and Routine at 4 or below.\n    excitement_tier is\n      pick 'Instant classic' when ExcitementIndex > 8\n      pick 'Thriller' when ExcitementIndex > 6\n      pick 'Competitive' when ExcitementIndex > 4\n      else 'Routine'\n\n  // ---- Season and week ---------------------------------------------\n  dimension:\n\n    #(doc) Season year as text, for example 2026. What the season picker filters on.\n    season_label is Season::string\n\n    #(doc) The week as a reader names it: Week 1 through Week 16 in the regular season, and Postseason for every bowl and College Football Playoff game.\n    // The feed numbers postseason weeks from 1 again, so \"Week 1\" alone\n    // would mix opening weekend with the bowls.\n    week_label is\n      pick 'Postseason' when SeasonType = 'postseason'\n      else concat('Week ', `Week`::string)\n\n    #(doc) Sort key for week_label, so Week 10 follows Week 9 and the postseason comes last.\n    week_sort is\n      pick 100 when SeasonType = 'postseason'\n      else `Week`\n\n  // ---- Line scores ---------------------------------------------------\n  //  HomeLineScores / AwayLineScores are comma-separated points per\n  //  period — \"7,10,0,14\", plus one entry per overtime period. They are\n  //  missing on a couple dozen completed games; everything here goes null\n  //  there, and the thrill index scores those games without late drama.\n  dimension:\n\n    #(doc) Number of periods the game went, from the line score: 4 for regulation, 5 or more when it went to overtime.\n    periods_played is length(HomeLineScores) - length(replace(HomeLineScores, ',', '')) + 1\n\n    #(doc) True when the game went to overtime.\n    is_overtime is periods_played > 4\n\n    #(doc) Home team's points through three quarters, from the line score.\n    home_points_after_three is\n      pick null when HomeLineScores is null\n      else coalesce(split_part!string(HomeLineScores, ',', 1):::number, 0)\n        + coalesce(split_part!string(HomeLineScores, ',', 2):::number, 0)\n        + coalesce(split_part!string(HomeLineScores, ',', 3):::number, 0)\n\n    #(doc) Away team's points through three quarters, from the line score.\n    away_points_after_three is\n      pick null when AwayLineScores is null\n      else coalesce(split_part!string(AwayLineScores, ',', 1):::number, 0)\n        + coalesce(split_part!string(AwayLineScores, ',', 2):::number, 0)\n        + coalesce(split_part!string(AwayLineScores, ',', 3):::number, 0)\n\n    #(doc) Home points minus away points going into the fourth quarter. Positive when the home team led.\n    margin_after_three is home_points_after_three - away_points_after_three\n\n    #(doc) True when the eventual winner was behind going into the fourth quarter.\n    is_comeback_win is\n      (HomePoints > AwayPoints and margin_after_three < 0)\n      or (AwayPoints > HomePoints and margin_after_three > 0)\n\n  // ---- Thrill index --------------------------------------------------\n  //  A 0-100 excitement score built from the box score alone, so it\n  //  exists for every completed game in every division — CFBD's own\n  //  ExcitementIndex (win-probability swings) is missing on most lower-\n  //  division games and lags days behind on new ones.\n  //\n  //    closeness     35   final margin: 35 at 0, falling to 0 at 28\n  //    late drama    20   margin entering the 4th: 20 at 0, 0 at 17\n  //    comeback      10   the winner trailed after three quarters\n  //    overtime      15   it went past regulation\n  //    scoring       12   combined points, full marks at 80\n  //    upset         10   the Elo underdog won, full marks at a 250 gap\n  //    stakes         8   College Football Playoff game\n  //\n  //  The parts sum past 100 on purpose and are capped: a one-point\n  //  overtime comeback does not need every box ticked to be a classic.\n  dimension:\n\n    #(doc) Thrill index points for how close the final score was: 35 for a one-possession finish at a margin of zero, falling to 0 at a 28-point margin.\n    thrill_closeness is 35 * greatest(0, 1 - victory_margin / 28.0)\n\n    #(doc) Thrill index points for how close the game was going into the fourth quarter: 20 when tied, falling to 0 at a 17-point margin. Zero when the line score is missing.\n    thrill_late_drama is coalesce(20 * greatest(0, 1 - abs(margin_after_three) / 17.0), 0)\n\n    #(doc) Thrill index points for a comeback: 10 when the winner trailed after three quarters.\n    thrill_comeback is pick 10 when is_comeback_win else 0\n\n    #(doc) Thrill index points for overtime: 15 when the game went past regulation.\n    thrill_overtime is pick 15 when is_overtime else 0\n\n    #(doc) Thrill index points for scoring: up to 12, reached at 80 combined points.\n    thrill_scoring is 12 * least(1, total_points / 80.0)\n\n    #(doc) Thrill index points for an upset: up to 10 when the team with the lower pregame Elo won, full marks at a 250-point rating gap.\n    thrill_upset is\n      pick 10 * least(1, abs(pregame_elo_edge) / 250.0) when is_elo_upset\n      else 0\n\n    #(doc) Thrill index points for stakes: 8 for a College Football Playoff game.\n    thrill_stakes is pick 8 when is_playoff_game else 0\n\n    #|(doc)\n      How exciting the game was, from 0 to 100, built from the box score so every completed\n      game has one: how close the final was, how close it was entering the fourth quarter,\n      whether the winner came from behind, overtime, combined scoring, an Elo upset, and\n      playoff stakes. Around 25 is a routine game; above 75 is an instant classic. Empty\n      until the game is played.\n    |#\n    thrill_index is\n      pick null when not Completed or HomePoints is null or AwayPoints is null\n      else round(least(100,\n        thrill_closeness + thrill_late_drama + thrill_comeback + thrill_overtime\n        + thrill_scoring + thrill_upset + thrill_stakes\n      ))\n\n    #(doc) Thrill index in words: Instant classic at 75 or more, Thriller at 55, Good game at 35, and Routine below that.\n    thrill_tier is\n      pick null when thrill_index is null\n      pick 'Instant classic' when thrill_index >= 75\n      pick 'Thriller' when thrill_index >= 55\n      pick 'Good game' when thrill_index >= 35\n      else 'Routine'\n\n  // ---- Measures ----------------------------------------------------\n  measure:\n\n    #(doc) Number of games.\n    game_count is count()\n\n    #(doc) Number of games that have been played and have a final score.\n    completed_game_count is count() { where: Completed }\n\n    #(doc) Total points scored by both teams across all games.\n    points_scored is sum(HomePoints) + sum(AwayPoints)\n\n    #(doc) Average combined points scored by both teams in a game.\n    avg_total_points is avg(total_points)\n\n    #(doc) Average points scored by the home team.\n    avg_home_points is avg(HomePoints)\n\n    #(doc) Average points scored by the away team.\n    avg_away_points is avg(AwayPoints)\n\n    #(doc) Average winning margin in points.\n    avg_victory_margin is avg(victory_margin)\n\n    #(doc) Share of completed games won by the home team.\n    # percent\n    home_win_rate is count() { where: home_win } / nullif(count() { where: Completed and HomePoints != AwayPoints }, 0)\n\n    #(doc) Share of games decided by 8 points or fewer.\n    # percent\n    one_score_game_rate is count() { where: victory_margin <= 8 } / nullif(completed_game_count, 0)\n\n    #(doc) Number of games decided by 28 points or more.\n    blowout_count is count() { where: victory_margin >= 28 }\n\n    #(doc) Number of games in which the team with the lower pregame Elo rating won.\n    upset_count is count() { where: is_elo_upset }\n\n    #(doc) Total announced attendance across all games that reported it, in people.\n    total_attendance is sum(Attendance)\n\n    #(doc) Average announced attendance per game, in people.\n    avg_attendance is avg(Attendance)\n\n    #(doc) Largest announced attendance for a single game, in people.\n    max_attendance is max(Attendance)\n\n    #(doc) Average excitement rating across games. Typical games rate near 4.\n    avg_excitement is avg(ExcitementIndex)\n\n    #(doc) Highest excitement rating of any game in the group.\n    max_excitement is max(ExcitementIndex)\n\n    #(doc) Average thrill index across completed games, 0 to 100.\n    avg_thrill_index is avg(thrill_index)\n\n    #(doc) Share of games played at a neutral venue.\n    # percent\n    neutral_site_rate is count() { where: NeutralSite } / nullif(game_count, 0)\n\n    #(doc) Share of games played between teams from the same conference.\n    # percent\n    conference_game_rate is count() { where: ConferenceGame } / nullif(game_count, 0)\n\n    #(doc) Average pregame Elo rating of the home team. Higher is stronger; roughly 1500 is average.\n    avg_home_pregame_elo is avg(HomePregameElo)\n\n    #(doc) Number of distinct teams appearing as the home team.\n    home_team_count is count(HomeTeam)\n\n  // ---- Views -------------------------------------------------------\n\n  #(doc) Games per week with scoring, margins and excitement, in schedule order. Answers how the season's weeks compare.\n  view: by_week is {\n    group_by: SeasonType, `Week`\n    aggregate: game_count, avg_total_points, avg_victory_margin, avg_excitement\n    order_by: SeasonType, `Week`\n  }\n\n  #(doc) Volume and scoring of games by the home team's conference, busiest conference first.\n  view: by_conference is {\n    where: HomeConference is not null\n    group_by: conference is HomeConference\n    aggregate: game_count, avg_total_points, avg_victory_margin, home_win_rate, avg_attendance\n    order_by: game_count desc\n  }\n\n  #(doc) Games by division matchup, for example FBS against FCS, showing how lopsided each type of matchup is.\n  view: by_classification is {\n    group_by: classification_matchup\n    aggregate: game_count, avg_total_points, avg_victory_margin\n    order_by: game_count desc\n  }\n\n  #(doc) The wildest finishes of the season, ranked by excitement rating.\n  view: most_exciting_games is {\n    where: Completed\n    group_by: game_date, matchup, final_score, ExcitementIndex\n    order_by: ExcitementIndex desc\n    limit: 25\n  }\n\n  #(doc) The most lopsided results of the season, ranked by winning margin.\n  view: biggest_blowouts is {\n    where: Completed\n    group_by: game_date, matchup, final_score, victory_margin\n    order_by: victory_margin desc\n    limit: 25\n  }\n\n  #(doc) The highest-scoring games of the season, ranked by combined points.\n  view: highest_scoring_games is {\n    where: Completed\n    group_by: game_date, matchup, final_score, total_points\n    order_by: total_points desc\n    limit: 25\n  }\n\n  #(doc) Best-attended games of the season, ranked by announced attendance.\n  view: best_attended_games is {\n    where: Attendance is not null\n    group_by: game_date, matchup, Venue, Attendance\n    order_by: Attendance desc\n    limit: 25\n  }\n\n  #(doc) Games won by the team the pregame Elo ratings rated lower, biggest rating gap first.\n  view: biggest_upsets is {\n    where: Completed and is_elo_upset\n    group_by: game_date, matchup, final_score, winner\n    aggregate: elo_gap is max(abs(pregame_elo_edge))\n    order_by: elo_gap desc\n    limit: 25\n  }\n\n  #(doc) The College Football Playoff bracket in round order, with each game's result.\n  view: playoff_bracket is {\n    where: is_playoff_game\n    group_by:\n      round_name is `Playoff RoundName`\n      bracket_slot is `Playoff BracketSlot`\n      bowl is `Playoff BowlName`\n      game_date\n      matchup\n      final_score\n    order_by: bracket_slot\n  }\n\n  #(doc) Season shape week by week: how many games are played and how many points are scored.\n  view: scoring_trend is {\n    group_by: game_date\n    aggregate: game_count, avg_total_points\n    order_by: game_date\n  }\n}\n","file:///givens.malloy":"##! experimental { givens }\n\n// =====================================================================\n//  GIVENS — the filter controls the dashboards expose\n//\n//  Every picker narrows to the ones before it: the conference list is\n//  the chosen season and division's conferences, the team list the\n//  chosen conference's teams. Each suggest query references the OTHER\n//  givens and never its own, so a list never collapses to its own pick.\n//  All of these round-trip through the URL as $NAME, so a filtered page\n//  is a shareable link.\n// =====================================================================\n\nimport \"index.malloy\"\n\ngiven:\n\n  #(doc) Season to show. The games reports pin their own season; the team rankings let the reader switch.\n  # label=\"Season\"\n  # control=select\n  # suggest { query=season_suggest dimension=season_label }\n  SEASON :: filter<string> is f'2026'\n\n  #(doc) Division to include: fbs, fcs, ii or iii. A game is included when either team plays in it. Empty shows every division.\n  # label=\"Division\"\n  # control=select\n  # suggest { query=division_suggest dimension=classification }\n  DIVISION :: filter<string> is f'fbs'\n\n  #(doc) Conference to include. A game is included when either team belongs to it. Empty shows every conference.\n  # label=\"Conference\"\n  # control=select\n  # suggest { query=conference_suggest dimension=conference }\n  CONFERENCE :: filter<string> is f''\n\n  #(doc) One team whose games to show. Empty shows every team. Narrows to the chosen conference when one is picked.\n  # label=\"Team\"\n  # control=select\n  # suggest { query=team_suggest dimension=team }\n  TEAM :: filter<string> is f''\n\n  #(doc) Week of the season to show: Week 1 through Week 16, or Postseason. Empty shows the whole season.\n  # label=\"Week\"\n  # control=select\n  # suggest { query=week_suggest dimension=week_label }\n  GAME_WEEK :: filter<string> is f''\n\n  #|(doc)\n    Leave out garbage-time possessions — the ones neither team is still playing to win —\n    from the drive-efficiency columns. Uses BCFtoys' garbage-possession rules. Records and\n    points per game always count every game.\n  |#\n  # label=\"Hide garbage drives\"\n  EXCLUDE_GARBAGE :: boolean is true\n\n#(doc) Every season in the data, newest first. Feeds the season picker.\nquery: season_suggest is team_games -> {\n  group_by: season_label\n  order_by: season_label desc\n}\n\n#(doc) Divisions with games in the chosen season. Feeds the division picker.\nquery: division_suggest is team_games -> {\n  where: season_label ~ $SEASON, classification is not null\n  group_by: classification\n  order_by: classification\n}\n\n#(doc) Conferences in the chosen season and division, alphabetically. Feeds the conference picker.\nquery: conference_suggest is team_games -> {\n  where: season_label ~ $SEASON, classification ~ $DIVISION, conference is not null\n  group_by: conference\n  order_by: conference\n}\n\n#(doc) Teams in the chosen season, division and conference, alphabetically. Feeds the team picker.\nquery: team_suggest is team_games -> {\n  where: season_label ~ $SEASON, classification ~ $DIVISION, conference ~ $CONFERENCE\n  group_by: team\n  order_by: team\n}\n\n#(doc) Weeks of the chosen season in calendar order, the postseason last. Feeds the week picker.\nquery: week_suggest is games -> {\n  where: season_label ~ $SEASON\n  group_by: week_label, week_sort\n  order_by: week_sort\n}\n","file:///index.malloy":"// =====================================================================\n//  INDEX — the published query surface, 2025 and 2026 seasons\n//\n//  games.malloy, drives.malloy and teams.malloy hold the documented base\n//  sources. This file joins games and drives on game id and exports the\n//  three consumer-facing sources:\n//\n//      games       -> one row per game,           with its drives joined in\n//      drives      -> one row per drive,          with its game joined in\n//      team_games  -> one row per team per game,  with both sides' drives\n// =====================================================================\n\nimport \"raw.malloy\"\nimport \"games.malloy\"\nimport \"drives.malloy\"\nimport \"teams.malloy\"\n\n#(doc) Number of drives the raw feed carries for each game. A cheap test for whether a game has drive detail, without building the full drive model.\nsource: game_drive_counts is drives_raw -> {\n  group_by: GameId\n  aggregate: drive_rows is count()\n}\n\n#|(doc)\n  One row per college football game in the 2025 and 2026 seasons, with every drive of that\n  game joined in. Carries the final score, line score, venue, conferences, Elo, CFBD's\n  excitement rating and a box-score thrill index, plus drive-level totals. Use it for\n  schedules, results, the most exciting games, and game summaries.\n|#\nsource: games is games_base extend {\n\n  #(doc) Every drive played in this game, one row per possession.\n  join_many: drives is drives_base on Id = drives.GameId\n\n  #(doc) How many drives the feed has for this game.\n  join_one: drive_counts is game_drive_counts on Id = drive_counts.GameId\n\n  dimension:\n\n    #(doc) True when this game has drive-by-drive detail, so a drive chart can be drawn. Division I games have it; Division II and III games do not.\n    has_drive_detail is coalesce(drive_counts.drive_rows, 0) > 0\n\n  measure:\n\n    #(doc) Number of drives (possessions) played.\n    drive_count is drives.count()\n\n    #(doc) Average points scored per possession by both teams combined.\n    points_per_drive is drives.points_per_drive\n\n    #(doc) Share of possessions that ended in a three-and-out punt.\n    # percent\n    three_and_out_rate is drives.three_and_out_rate\n}\n\n#|(doc)\n  One row per drive (possession) of the 2025 and 2026 college football seasons, with the game\n  it was played in joined in. Use it for offensive and defensive drive efficiency, Eckel rate,\n  field position, scoring rates, and drive-by-drive game charts.\n|#\nsource: drives is drives_base extend {\n\n  #(doc) The game this drive was played in, with its date, teams, venue and final score.\n  join_one: game is games_base on GameId = game.Id\n\n  dimension:\n\n    #(doc) Season the drive was played in, as text, for example 2026.\n    season_label is game.season_label\n\n    #(doc) Home team of the game this drive was played in.\n    home_team is game.HomeTeam\n\n    #(doc) Away team of the game this drive was played in.\n    away_team is game.AwayTeam\n\n  #(doc) Every possession of one game, in order, with the geometry and score ledger a drive chart draws from. Filter it to a single GameId.\n  view: game_drive_chart is {\n    group_by:\n      drive_id is Id\n      game_id is GameId\n      home_team\n      away_team\n      drive_number is DriveNumber\n      offense is Offense\n      defense is Defense\n      is_home_offense is IsHomeOffense\n      quarter_label\n      start_period is StartPeriod\n      // absolute field coordinates: 0 = the goal line the away team\n      // attacks, 100 = the goal line the home team attacks\n      start_yardline is chart_start_yardline\n      end_yardline is chart_end_yardline\n      start_field_position\n      end_field_position\n      plays is Plays\n      yards is Yards\n      result_category\n      result_abbreviation\n      drive_points\n      defensive_points_scored\n      defensive_score_type\n      home_score_after\n      away_score_after\n    order_by: drive_number\n  }\n}\n\nexport { games, drives, team_games }\n","file:///raw.malloy":"// =====================================================================\n//  RAW — the CFBD game and drive feeds, both seasons, straight from\n//  Hugging Face (huggingface.co/datasets/24601p/cfb-data).\n//\n//  Read over https rather than from a local copy, so the published site\n//  picks up each pipeline upload (cfbd_pipeline.py --upload) without a\n//  rebuild: the 2026 files grow every week of the season.\n//\n//  Every season lives in its own file with an identical schema;\n//  read_parquet's list form stacks them. Add a season by adding a URL.\n//  Game ids and drive ids are unique across seasons (checked: no overlap\n//  between 2025 and 2026), so the window functions downstream, which\n//  partition by GameId, never mix two seasons.\n// =====================================================================\n\n#(doc) Every game of every season in the feed, one row per game, exactly as CFBD publishes it.\nsource: games_raw is duckdb.sql(\"\"\"\n  SELECT * FROM read_parquet([\n    'https://huggingface.co/datasets/24601p/cfb-data/resolve/main/games-2025.parquet',\n    'https://huggingface.co/datasets/24601p/cfb-data/resolve/main/games-2026.parquet'\n  ], union_by_name = true)\n\"\"\")\n\n#(doc) Every drive of every season in the feed, one row per possession, exactly as CFBD publishes it.\nsource: drives_raw is duckdb.sql(\"\"\"\n  SELECT * FROM read_parquet([\n    'https://huggingface.co/datasets/24601p/cfb-data/resolve/main/drives-2025.parquet',\n    'https://huggingface.co/datasets/24601p/cfb-data/resolve/main/drives-2026.parquet'\n  ], union_by_name = true)\n\"\"\")\n\n// ---------------------------------------------------------------------\n//  TEAM-GAMES — each game twice, once from each team's side.\n//\n//  A ranking is asked per team, but a game row names two teams in two\n//  differently named columns. Unpivoting here gives one row per team per\n//  game, so \"points allowed\" is just points_against and a team's record\n//  is a count over its own rows — no pick-the-right-column logic in every\n//  measure. Malloy has no UNION, which is why this one lives in SQL.\n// ---------------------------------------------------------------------\n\n#(doc) One row per team per game: every game appears twice, once from the home team's side and once from the away team's.\nsource: team_games_raw is duckdb.sql(\"\"\"\n  WITH g AS (\n    SELECT * FROM read_parquet([\n      'https://huggingface.co/datasets/24601p/cfb-data/resolve/main/games-2025.parquet',\n      'https://huggingface.co/datasets/24601p/cfb-data/resolve/main/games-2026.parquet'\n    ], union_by_name = true)\n  ),\n  sides AS (\n    SELECT Id AS game_id, Season AS season, \"Week\" AS week_number, SeasonType AS season_type,\n      StartDate AS start_date, Completed AS completed, ConferenceGame AS conference_game,\n      TRUE AS is_home, HomeTeam AS team, HomeConference AS conference, HomeClassification AS classification,\n      AwayTeam AS opponent, AwayConference AS opponent_conference, AwayClassification AS opponent_classification,\n      HomePoints AS points_for, AwayPoints AS points_against,\n      HomePregameElo AS pregame_elo, HomePostgameElo AS postgame_elo, AwayPregameElo AS opponent_pregame_elo\n    FROM g\n    UNION ALL\n    SELECT Id, Season, \"Week\", SeasonType,\n      StartDate, Completed, ConferenceGame,\n      FALSE, AwayTeam, AwayConference, AwayClassification,\n      HomeTeam, HomeConference, HomeClassification,\n      AwayPoints, HomePoints,\n      AwayPregameElo, AwayPostgameElo, HomePregameElo\n    FROM g\n  )\n  SELECT *,\n    CAST(game_id AS VARCHAR) || '|' || team AS team_game_id,\n    -- the team's most recent game that carries a postgame Elo, so a\n    -- ranking can show where the rating stands now\n    postgame_elo IS NOT NULL\n      AND row_number() OVER (\n        PARTITION BY team, season, postgame_elo IS NULL ORDER BY start_date DESC\n      ) = 1 AS is_latest_rated_game\n  FROM sides\n\"\"\")\n","file:///teams.malloy":"// =====================================================================\n//  TEAM-GAMES — one row per team per game\n//\n//  The grain a team ranking is asked at. Every game appears twice, once\n//  from each side (see team_games_raw in raw.malloy), and each row joins\n//  the drives that team ran and the drives it defended in that game.\n//\n//  The two join_many's fan a row out to offense drives x defense drives\n//  (about 12 x 12 per game). Malloy's symmetric aggregates keep every\n//  measure exact through that — count() counts team-games, not the\n//  fanned-out rows, and offense_drives.points_per_drive averages at the\n//  drive grain.\n// =====================================================================\n\nimport \"raw.malloy\"\nimport \"drives.malloy\"\n\n#|(doc)\n  One row per team per game in the 2025 and 2026 seasons: every game appears twice, once\n  from each team's side, with points for and against, the team's and opponent's conference\n  and division, and pregame and postgame Elo. Joins the drives the team ran and the drives it\n  defended, so a team's record, scoring margin and drive efficiency on both sides of the ball\n  come from one source. Use it for team rankings, records and strength of schedule.\n|#\nsource: team_games is team_games_raw extend {\n\n  primary_key: team_game_id\n\n  #(doc) The drives this team ran on offense in this game.\n  join_many: offense_drives is drives_base on game_id = offense_drives.GameId and team = offense_drives.Offense\n\n  #(doc) The drives this team defended in this game — its opponent's possessions.\n  join_many: defense_drives is drives_base on game_id = defense_drives.GameId and team = defense_drives.Defense\n\n  dimension:\n\n    #(doc) Season year as text, for example 2026. What the season picker filters on.\n    season_label is season::string\n\n    #(doc) The week as a reader names it: Week 1 through Week 16, or Postseason.\n    week_label is\n      pick 'Postseason' when season_type = 'postseason'\n      else concat('Week ', week_number::string)\n\n    #(doc) True when the game is over and this team won it.\n    is_win is completed and points_for > points_against\n\n    #(doc) True when the game is over and this team lost it.\n    is_loss is completed and points_for < points_against\n\n    #(doc) This team's points minus its opponent's.\n    scoring_margin is points_for - points_against\n\n  measure:\n\n    #(doc) Number of completed games played.\n    games_played is count() { where: completed }\n\n    #(doc) Games won.\n    wins is count() { where: is_win }\n\n    #(doc) Games lost.\n    losses is count() { where: is_loss }\n\n    #(doc) Share of completed games won.\n    # percent\n    win_rate is count() { where: is_win } / nullif(count() { where: completed }, 0)\n\n    #(doc) Average points scored per completed game.\n    points_per_game is avg(points_for) { where: completed }\n\n    #(doc) Average points allowed per completed game.\n    points_allowed_per_game is avg(points_against) { where: completed }\n\n    #(doc) Average scoring margin per completed game. Positive means the team outscores its opponents.\n    avg_scoring_margin is avg(scoring_margin) { where: completed }\n\n    #(doc) The team's Elo rating after its most recent rated game: where the rating stands now. Higher is stronger; roughly 1500 is average.\n    current_elo is max(postgame_elo) { where: is_latest_rated_game }\n\n    #(doc) Strength of schedule: the average pregame Elo rating of the opponents played. Higher means a tougher schedule.\n    strength_of_schedule is avg(opponent_pregame_elo) { where: completed }\n}\n"};
window.__TABLE_FILES__ = {};
